#!/usr/bin/env bash
# Regenerates compat/gmp.h and compat/mpfr.h from the PBN_API declarations in pocketbignum.h
set -euo pipefail
cd "$(dirname "$0")/.."
H=pocketbignum.h
names() { grep -oE "PBN_API [^;]*\b$1_[a-z0-9_]+\(" "$H" | grep -oE "$1_[a-z0-9_]+" | grep -v -E 'srcptr|_ptr$' | sort -u; }

{
cat <<'HDR'
/*
 * GMP-compatible facade for PocketBignum (generated by tools_gen_compat.sh).
 * Covers the mpz/mpq subset PocketBignum implements. MIT License.
 */
#ifndef POCKETBIGNUM_GMP_COMPAT_H
#define POCKETBIGNUM_GMP_COMPAT_H

#include "../pocketbignum.h"

#define __GNU_MP__                   6
#define __GNU_MP_VERSION             6
#define __GNU_MP_VERSION_MINOR       3
#define __GNU_MP_VERSION_PATCHLEVEL  0
#define GMP_LIMB_BITS                PBN_LIMB_BITS
#define GMP_NUMB_BITS                PBN_LIMB_BITS
#define mp_bits_per_limb             PBN_LIMB_BITS
#define gmp_version                  pbn_version

typedef pbn_limb        mp_limb_t;
typedef pbn_size        mp_size_t;
typedef pbn_bitcnt      mp_bitcnt_t;
typedef long            mp_exp_t;
typedef pbn_limb       *mp_ptr;
typedef const pbn_limb *mp_srcptr;

typedef pbz_struct      __mpz_struct;
typedef pbz_struct      MP_INT;
typedef pbz_t           mpz_t;
typedef pbz_ptr         mpz_ptr;
typedef pbz_srcptr      mpz_srcptr;

typedef pbq_struct      __mpq_struct;
typedef pbq_struct      MP_RAT;
typedef pbq_t           mpq_t;
typedef pbq_ptr         mpq_ptr;
typedef pbq_srcptr      mpq_srcptr;

#define mp_set_memory_functions pbn_set_memory_functions
#define mp_get_memory_functions pbn_get_memory_functions

#define mpz_sgn                  pbz_sgn
#define mpz_odd_p                pbz_odd_p
#define mpz_even_p               pbz_even_p
#define mpq_sgn                  pbq_sgn
#define mpq_numref               pbq_numref
#define mpq_denref               pbq_denref
#define _mpq_cmp_si              pbq_cmp_si
#define _mpq_cmp_ui              pbq_cmp_ui
#define _mpz_cmp_si              pbz_cmp_si
#define _mpz_cmp_ui              pbz_cmp_ui

HDR
for n in $(names pbz) $(names pbq); do printf "#define mp%-22s %s\n" "${n#pb}" "$n"; done
printf "\n#endif /* POCKETBIGNUM_GMP_COMPAT_H */\n"
} > compat/gmp.h

{
cat <<'HDR'
/*
 * MPFR-compatible facade for PocketBignum (generated by tools_gen_compat.sh).
 * Covers the mpfr subset PocketBignum implements. MIT License.
 */
#ifndef POCKETBIGNUM_MPFR_COMPAT_H
#define POCKETBIGNUM_MPFR_COMPAT_H

#include "gmp.h"

#define MPFR_VERSION_MAJOR    4
#define MPFR_VERSION_MINOR    2
#define MPFR_VERSION_PATCHLEVEL 1
#define MPFR_VERSION_STRING   PBN_VERSION
#define MPFR_PREC_MIN         PBF_PREC_MIN
#define MPFR_PREC_MAX         PBF_PREC_MAX

typedef pbf_prec_t  mpfr_prec_t;
typedef pbf_sign_t  mpfr_sign_t;
typedef pbf_exp_t   mpfr_exp_t;
typedef pbf_rnd_t   mpfr_rnd_t;
typedef pbf_struct  __mpfr_struct;
typedef pbf_t       mpfr_t;
typedef pbf_ptr     mpfr_ptr;
typedef pbf_srcptr  mpfr_srcptr;

#define MPFR_RNDN   PBF_RNDN
#define MPFR_RNDZ   PBF_RNDZ
#define MPFR_RNDU   PBF_RNDU
#define MPFR_RNDD   PBF_RNDD
#define MPFR_RNDA   PBF_RNDA
#define MPFR_RNDF   PBF_RNDF
#define MPFR_RNDNA  PBF_RNDNA
#define GMP_RNDN    PBF_RNDN
#define GMP_RNDZ    PBF_RNDZ
#define GMP_RNDU    PBF_RNDU
#define GMP_RNDD    PBF_RNDD

HDR
for n in $(names pbf); do printf "#define mpfr_%-20s %s\n" "${n#pbf_}" "$n"; done
printf "\n#endif /* POCKETBIGNUM_MPFR_COMPAT_H */\n"
} > compat/mpfr.h
